namespace Contoso.Text.Tests;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    // ── FormatPhoneNumber ───────────────────────────────────────

    [TestMethod]
    public void FormatPhoneNumber_ReturnsParenthesizedAreaCode()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");
        StringAssert.StartsWith(result, "(212)");
    }

    [TestMethod]
    public void FormatPhoneNumber_EndsWithLastFourDigits()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");
        StringAssert.EndsWith(result, "-1234");
    }

    [TestMethod]
    public void FormatPhoneNumber_ContainsExchangeCode()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");
        StringAssert.Contains(result, "555");
    }

    [TestMethod]
    public void FormatPhoneNumber_MatchesFullPattern()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");
        StringAssert.Matches(result, new(@"^\(\d{3}\) \d{3}-\d{4}$"));
    }

    [TestMethod]
    public void FormatPhoneNumber_FullValue()
    {
        var result = _formatter.FormatPhoneNumber("2125551234");
        Assert.AreEqual("(212) 555-1234", result);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void FormatPhoneNumber_NullThrows()
    {
        _formatter.FormatPhoneNumber(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void FormatPhoneNumber_WrongLengthThrows()
    {
        _formatter.FormatPhoneNumber("123");
    }

    // ── BuildGreeting ───────────────────────────────────────────

    [TestMethod]
    public void BuildGreeting_StartsWithDear()
    {
        var result = _formatter.BuildGreeting("Smith");
        StringAssert.StartsWith(result, "Dear ");
    }

    [TestMethod]
    public void BuildGreeting_EndsWithComma()
    {
        var result = _formatter.BuildGreeting("Smith");
        StringAssert.EndsWith(result, ",");
    }

    [TestMethod]
    public void BuildGreeting_ContainsName()
    {
        var result = _formatter.BuildGreeting("Smith");
        StringAssert.Contains(result, "Smith");
    }

    [TestMethod]
    public void BuildGreeting_DefaultTitle()
    {
        var result = _formatter.BuildGreeting("Smith");
        Assert.AreEqual("Dear Mr. Smith,", result);
    }

    [TestMethod]
    public void BuildGreeting_CustomTitle()
    {
        var result = _formatter.BuildGreeting("Smith", "Dr.");
        StringAssert.StartsWith(result, "Dear Dr.");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void BuildGreeting_WhitespaceNameThrows()
    {
        _formatter.BuildGreeting("   ");
    }

    // ── GenerateSlug ────────────────────────────────────────────

    [TestMethod]
    public void GenerateSlug_LowercasesAndHyphenates()
    {
        var result = _formatter.GenerateSlug("Hello World");
        Assert.AreEqual("hello-world", result);
    }

    [TestMethod]
    public void GenerateSlug_MatchesSlugPattern()
    {
        var result = _formatter.GenerateSlug("  My Great Post!  ");
        StringAssert.Matches(result, new(@"^[a-z0-9]+(-[a-z0-9]+)*$"));
    }

    [TestMethod]
    public void GenerateSlug_DoesNotStartWithHyphen()
    {
        var result = _formatter.GenerateSlug("---leading");
        StringAssert.DoesNotMatch(result, new(@"^-"));
    }

    [TestMethod]
    public void GenerateSlug_DoesNotEndWithHyphen()
    {
        var result = _formatter.GenerateSlug("trailing---");
        StringAssert.DoesNotMatch(result, new(@"-$"));
    }

    [TestMethod]
    public void GenerateSlug_SpecialCharacters()
    {
        var result = _formatter.GenerateSlug("C# is fun!!");
        Assert.AreEqual("c-is-fun", result);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void GenerateSlug_WhitespaceThrows()
    {
        _formatter.GenerateSlug("  ");
    }

    // ── FormatCurrency ──────────────────────────────────────────

    [TestMethod]
    public void FormatCurrency_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(9.99m);
        StringAssert.StartsWith(result, "$");
    }

    [TestMethod]
    public void FormatCurrency_EndsWithTwoDecimalPlaces()
    {
        var result = _formatter.FormatCurrency(10m);
        StringAssert.EndsWith(result, ".00");
    }

    [TestMethod]
    public void FormatCurrency_MatchesPattern()
    {
        var result = _formatter.FormatCurrency(1234.5m);
        StringAssert.Matches(result, new(@"^\$\d+\.\d{2}$"));
    }

    [TestMethod]
    public void FormatCurrency_CustomSymbol()
    {
        var result = _formatter.FormatCurrency(19.99m, "€");
        StringAssert.StartsWith(result, "€");
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount()
    {
        var result = _formatter.FormatCurrency(-5.50m);
        StringAssert.Contains(result, "-");
        StringAssert.EndsWith(result, "5.50");
    }
}

